  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    # Build maps
    node_map = {}
    children_map = {}
    for node in nodes:
        nid = node['id']
        node_map[nid] = node
        children_map.setdefault(node['parent'], []).append(nid)

    # root detection
    root_id = None
    for node in nodes:
        if node['parent'] is None:
            root_id = node['id']
            break

    retained = set(node_map.keys())
    # Global symbol counts
    global_count = {}
    for node in nodes:
        sym = node['symbol']
        global_count[sym] = global_count.get(sym, 0) + 1

    # Candidates: all node ids, sorted by depth desc, then id asc
    candidates = sorted(node_map.keys(), key=lambda nid: (-node_map[nid]['depth'], nid))
    removed = []

    for nid in candidates:
        if nid not in retained:
            continue
        node = node_map[nid]
        # Never remove root
        if node['parent'] is None:
            continue
        # Never remove required symbol
        if node['symbol'] in required_symbols:
            continue
        # Removable flag
        if not node['removable']:
            continue
        # Has retained children?
        child_ids = children_map.get(nid, [])
        has_retained_child = any(cid in retained for cid in child_ids)
        if has_retained_child:
            continue
        # Compute subtree retained nodes
        stack = [nid]
        subtree_nodes = []
        while stack:
            cur = stack.pop()
            if cur in retained:
                subtree_nodes.append(cur)
                for child in children_map.get(cur, []):
                    stack.append(child)
        # Compute subtree symbol counts for required symbols only
        subtree_counts = {}
        for snid in subtree_nodes:
            sym = node_map[snid]['symbol']
            if sym in required_symbols:
                subtree_counts[sym] = subtree_counts.get(sym, 0) + 1
        # Check if removal would eliminate any required symbol
        safe = True
        for rs in required_symbols:
            global_rs = global_count.get(rs, 0)
            sub_rs = subtree_counts.get(rs, 0)
            if global_rs - sub_rs <= 0:
                safe = False
                break
        if not safe:
            continue
        # Remove the entire subtree in deterministic order (deepest first, then id)
        subtree_nodes.sort(key=lambda x: (-node_map[x]['depth'], x))
        for snid in subtree_nodes:
            retained.remove(snid)
            sym = node_map[snid]['symbol']
            global_count[sym] -= 1
            if global_count[sym] == 0:
                del global_count[sym]
        removed.extend(subtree_nodes)

    retained_sorted = sorted(retained)
    return {"removed_node_ids": removed, "retained_node_ids": retained_sorted}
